def cache(timeout, key_func=None):
    """Caches a function results for timeout seconds."""
    if isinstance(timeout, int):
        timeout = timedelta(seconds=timeout)

    if key_func is None:
        key_func = lambda *a, **kw: a + tuple(sorted(kw.items())) if kw else a

    def decorator(func):
        cache_store = {}

        @wraps(func)
        def wrapper(*args, **kwargs):
            key = key_func(*args, **kwargs)
            if key in cache_store:
                result, timestamp = cache_store[key]
                if datetime.now() - timestamp < timeout:
                    return result
                else:
                    del cache_store[key]

            try:
                result = func(*args, **kwargs)
            except SkipMemoization as e:
                # Bypass caching: return the result but don't cache it
                return e.args[0] if e.args else None

            cache_store[key] = result, datetime.now()
            return result

        # Expose memory as the cache store dict
        wrapper.memory = cache_store

        def invalidate(*args, **kwargs):
            key = key_func(*args, **kwargs)
            cache_store.pop(key, None)
        wrapper.invalidate = invalidate

        def invalidate_all():
            cache_store.clear()
        wrapper.invalidate_all = invalidate_all

        return wrapper
    return decorator

